SELECT t.Team_Name FROM dbo.HS_Team_Names t WHERE t.Team_Name LIKE '%(LA)' AND (t.Team_Name LIKE '%Olive%' OR t.Team_Name LIKE '%Berchmans%' OR t.Team_Name LIKE '%Ellender%' OR t.Team_Name LIKE '%Teurlings%' OR t.Team_Name LIKE '%Higgins%' OR t.Team_Name LIKE '%Rummel%' OR t.Team_Name LIKE '%Tensas%' OR t.Team_Name LIKE '%Shreve%' OR t.Team_Name LIKE '%Holy Savior%' OR t.Team_Name LIKE '%Booker T. Washington%' OR t.Team_Name LIKE '%Warren Easton%' OR t.Team_Name LIKE 'Buras%' OR t.Team_Name LIKE 'Rosedale%' OR t.Team_Name LIKE 'Moss Bluff%' OR t.Team_Name LIKE '%Liberty Magnet%' OR t.Team_Name LIKE '%Willow%' OR t.Team_Name LIKE 'Grambling%' OR t.Team_Name LIKE '%University Christian Prep%' OR t.Team_Name LIKE '%Sunset%' OR t.Team_Name LIKE 'Farmerville%' OR t.Team_Name LIKE 'Waterproof%' OR t.Team_Name LIKE 'Mansfield%') ORDER BY 1;
